"""T39 — auto-generated MAGEConfig reference table (the source for docs/CONFIG.md).

Introspects every ``MAGEConfig`` field (name, type, default), joins it with the
``MAGE_*`` env-var map and the config profiles under ``configs/``, and renders a
Markdown table. Run ``python -m mmar_mage.config_docs`` to refresh
``docs/CONFIG.md``; the drift test (``tests/test_config_docs.py``) fails when the
committed file diverges, so a newly-added field or profile surfaces itself.
"""

from __future__ import annotations

import tomllib
from pathlib import Path
from typing import Any

from pydantic_core import PydanticUndefined

from .schemas import MAGEConfig

_ROOT = Path(__file__).resolve().parent.parent
_CONFIGS_DIR = _ROOT / "configs"
_OUTPUT = _ROOT / "docs" / "CONFIG.md"


def _fmt_default(field: Any) -> str:
    if field.default_factory is not None:
        return "(factory)"
    default = field.default
    if default is PydanticUndefined:
        return "(required)"
    if isinstance(default, str):
        return f'"{default}"'
    return repr(default)


def _fmt_type(annotation: Any) -> str:
    text = str(annotation)
    if text.startswith("<class '") and text.endswith("'>"):  # bare class → "str"
        text = text[len("<class '") : -2]
    text = text.replace("typing.", "").replace("NoneType", "None")
    return text.replace("mmar_mage.schemas.", "").replace("builtins.", "")


def _profile_field_sets() -> dict[str, set[str]]:
    out: dict[str, set[str]] = {}
    for path in sorted(_CONFIGS_DIR.glob("*.toml")):
        mage = tomllib.loads(path.read_text(encoding="utf-8")).get("mage", {})
        out[path.stem] = set(mage)
    return out


def generate_config_table() -> str:
    """Render the full MAGEConfig reference as Markdown (deterministic)."""
    field_to_env = {field: env for env, field in MAGEConfig._env_var_map().items()}
    profiles = _profile_field_sets()
    profile_names = sorted(profiles)

    lines = [
        "# MAGEConfig reference",
        "",
        "_Auto-generated by `mmar_mage.config_docs.generate_config_table` (T39) — do NOT edit by hand._",
        "_Run `python -m mmar_mage.config_docs` to regenerate; `tests/test_config_docs.py` fails if stale._",
        "",
        "| Field | Type | Default | Env var | Set in profiles |",
        "|---|---|---|---|---|",
    ]
    for name, field in MAGEConfig.model_fields.items():
        env = field_to_env.get(name)
        env_cell = f"`{env}`" if env else "—"
        set_in = ", ".join(p for p in profile_names if name in profiles[p]) or "—"
        lines.append(
            f"| `{name}` | `{_fmt_type(field.annotation)}` | `{_fmt_default(field)}` | {env_cell} | {set_in} |"
        )
    return "\n".join(lines) + "\n"


def main() -> None:
    _OUTPUT.write_text(generate_config_table(), encoding="utf-8")
    print(f"wrote {_OUTPUT.relative_to(_ROOT)}")


if __name__ == "__main__":
    main()
